      var i;
      for (i = 0; i < FONT_DEFS.length; i++) if (FONT_DEFS[i].embed) robIdx = i;
      if (robIdx >= 0 && all.some(function (e2) { return e2.props && String(e2.props.fontFamily) === String(robIdx); })) {
        headCss += "/* Roboto — Apache License 2.0 (google/fonts). */\n"
          + "@font-face{font-family:'Roboto';font-style:normal;font-weight:100 900;font-display:swap;"
          + 'src:url(data:font/woff2;base64,' + ROBOTO_B64 + ") format('woff2');unicode-range:" + ROBOTO_RANGE + '}\n';
      }
