    // ---------- history ----------
    function pushHistory() {
      undoStack.push(JSON.stringify(state));
      if (undoStack.length > 50) undoStack.shift();
      redoStack = [];
      updateUndoBtns();
    }
    // Sürüşdürmə/ölçü dəyişməsi kimi davamlı əməliyyatlarda əvvəlki vəziyyəti
    // əməliyyat başlamazdan əvvəl saxlayırıq və yalnız faktiki dəyişiklik olarsa
    // stekə əlavə edirik.
    function commitIfChanged(pre) {
      if (JSON.stringify(state) === pre) return;
      undoStack.push(pre);
      if (undoStack.length > 50) undoStack.shift();
      redoStack = [];
      updateUndoBtns();
      syncOutput();
    }
    function undo() {
      if (!undoStack.length) return;
      redoStack.push(JSON.stringify(state));
      state = JSON.parse(undoStack.pop());
      afterRestore();
    }
    function redo() {
      if (!redoStack.length) return;
      undoStack.push(JSON.stringify(state));
      state = JSON.parse(redoStack.pop());
      afterRestore();
    }
    function afterRestore() {
      if (selId && !byId(selId)) selId = null;
      editing = false;
      renderAll();
      updateUndoBtns();
    }
    function updateUndoBtns() {
      if (undoBtn) undoBtn.disabled = !undoStack.length;
      if (redoBtn) redoBtn.disabled = !redoStack.length;
    }

    // ---------- helpers ----------
    function byId(id) {
      for (var i = 0; i < ELS().length; i++) if (ELS()[i].id === id) return ELS()[i];
      return null;
    }
    function sel() { return selId ? byId(selId) : null; }
    function snapN(v) { return snapEl && snapEl.checked ? Math.round(v / 5) * 5 : Math.round(v); }
    // Kanvas miqyası: eni kiçik ekranlarda artboard scale ilə sığdırılır.
    // Cihaz rejimi (deviceW=768/390): kanvas DƏqiq generasiya olunmuş səhifənin
