          st = bgCss(p.bg, p.grad)
            + (bw > 0 && p.borderStyle !== 'none' ? 'border:' + bw + 'px ' + (p.borderStyle === 'dashed' ? 'dashed' : 'solid') + ' ' + p.borderC + ';' : '')
            + 'border-radius:' + num(p.radius, 0, 100, 0) + 'px;' + shadowCss(p.shadow)
            + 'display:flex;align-items:center;justify-content:' + alignJustify(p.align) + ';padding:8px;';
