    function contrastRatio(a, b) {
      var la = hexLum(a), lb = hexLum(b);
      if (la == null || lb == null) return 21;
      return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
    }
    function contrastText(bg) {
      var l = hexLum(bg);
      if (l == null) return '#111827';
      return l > 0.35 ? '#111827' : '#ffffff';
    }

    function computeTips() {
      var tips = [];
      var els = ELS();
      var i;
      // Formu üfüqi mərkəzlə
      for (i = 0; i < els.length; i++) {
        if (els[i].type === 'form' && Math.abs(els[i].x + els[i].w / 2 - state.w / 2) > 10) {
          (function (f) {
            tips.push({ id: 'tip_center_form', apply: function () { f.x = Math.round((state.w - f.w) / 2); } });
          })(els[i]);
          break;
        }
      }
      // Sol kənarları hizala (yaxın-x qrupu)
      if (els.length >= 2) {
        var minX = Infinity, maxX = -Infinity;
        for (i = 0; i < els.length; i++) { minX = Math.min(minX, els[i].x); maxX = Math.max(maxX, els[i].x); }
        if (maxX - minX > 0 && maxX - minX <= 10) {
          tips.push({ id: 'tip_align_left', apply: function () { for (var j = 0; j < ELS().length; j++) ELS()[j].x = minX; } });
        }
      }
      // Enləri bərabərləşdir (yaxın-en qrupu)
      if (els.length >= 2) {
        var minW2 = Infinity, maxW2 = -Infinity;
        for (i = 0; i < els.length; i++) { minW2 = Math.min(minW2, els[i].w); maxW2 = Math.max(maxW2, els[i].w); }
        if (maxW2 - minW2 > 0 && maxW2 - minW2 <= 10) {
          tips.push({ id: 'tip_equal_width', apply: function () { for (var j = 0; j < ELS().length; j++) ELS()[j].w = maxW2; } });
        }
      }
      // Şaquli məsafələri bərabərləşdir (ütüşməyən, üst-üstə düzülmüş elementlər)
      var stacked = els.slice().sort(function (a, b) { return a.y - b.y; });
      var seqEls = [], lastBottom = -Infinity;
      for (i = 0; i < stacked.length; i++) {
        if (stacked[i].y >= lastBottom - 2) { seqEls.push(stacked[i]); lastBottom = stacked[i].y + stacked[i].h; }
      }
      if (seqEls.length >= 3) {
        var gaps = [];
        for (i = 1; i < seqEls.length; i++) gaps.push(seqEls[i].y - (seqEls[i - 1].y + seqEls[i - 1].h));
        var gMin = Math.min.apply(null, gaps), gMax = Math.max.apply(null, gaps);
        if (gMax - gMin > 8) {
          var avg = Math.round(gaps.reduce(function (a, b) { return a + b; }, 0) / gaps.length);
          tips.push({
            id: 'tip_spacing',
            apply: function () {
              var y = seqEls[0].y;
              for (var j = 0; j < seqEls.length; j++) { seqEls[j].y = y; y += seqEls[j].h + avg; }
            }
          });
        }
      }
      // Kontrast (mətn/fon nisbəti < 3 olan ilk element)
      for (i = 0; i < els.length; i++) {
        var e2 = els[i], p2 = e2.props;
        if (e2.type !== 'text' && e2.type !== 'rect' && e2.type !== 'button') continue;
        if (!p2.text) continue;
        var bg = e2.type === 'text' ? P().bg : p2.bg;
        if (contrastRatio(p2.color, bg) < 3) {
          (function (el3, bgc) {
            tips.push({ id: 'tip_contrast', apply: function () { el3.props.color = contrastText(bgc); } });
          })(e2, bg);
          break;
        }
      }
      return tips;
    }

